typedef struct String_s {
    uintptr_t len;
    char* bytes;
} String;

enum Object_Type {
    Object_INTEGER,
    Object_STRING,
    Object_LIST,
    Object_DICT,
    Object_UNPARSABLE
};

typedef struct {
    enum Object_Type type;
    union {
        int64_t number;
        String_t* string;
        List_t* list;
        Dict_t* dictionary;
    } as;
} Object;

struct Allocator_OnFreeJob;
typedef void (* Allocator_OnFreeCallback)(struct Allocator_OnFreeJob* job);
struct Allocator_OnFreeJob
{
    /** Set by caller. */
    Allocator_OnFreeCallback callback;
    void* userData;
    Identity
};

typedef struct List_Item List_Item_t;
struct List_Item {
    List_Item_t* next;
    Object* elem;
};

typedef struct Dict_Entry Dict_Entry_t;
struct Dict_Entry {
    Dict_Entry_t* next;
    String* key;
    Object* val;
};

