import random
from typing import List

# Target data type: binary blob
# Ensure outputs are valid bytes and avoid invalid UTF-16 surrogate literals in Python.

MAX_TOTAL = 4096

ASCII_WORDS = [
    b"",
    b"hello",
    b"world",
    b"allocator",
    b"dictionary",
    b"list",
    b"string",
    b"integer",
    b"nested",
    b"unicode",
]

# Valid UTF-8 strings (avoid surrogate code points). Use explicit code points.
UTF8_FRAGMENTS = [
    "\u2603",        # snowman
    "\u20AC",        # euro
    "\u00A9",        # copyright
    "\U0001F600",    # 😀
    "\u4F60\u597D",  # 你好
    "\U0001F680",    # 🚀
]

# Precomputed binary chunks with edge-case bytes
BIN_CHUNKS = [
    bytes(range(0, 256)),                # 0..255
    bytes(range(255, -1, -1)),           # 255..0
    b"\x00" * 64,                        # zeros
    b"\xFF" * 64,                        # 0xFFs
    b"\x00\xFF" * 32,
    b"\x7F\x80" * 32,
]

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))

def _mk_ascii_blob(rng: random.Random, target_len: int) -> bytes:
    parts: List[bytes] = []
    cur = 0
    while cur < target_len:
        choice = rng.randrange(4)
        if choice == 0:
            chunk = rng.choice(ASCII_WORDS) + b" "
        elif choice == 1:
            n = rng.randint(1, 16)
            pool = b"0123456789:-_.,/\\\n\t"
            chunk = bytes(rng.choice(pool) for _ in range(n))
        elif choice == 2:
            ch = rng.randrange(32, 127)
            chunk = bytes([ch]) * rng.randint(1, 32)
        else:
            chunk = _rand_bytes(rng, rng.randint(1, 8))
        take = min(len(chunk), target_len - cur)
        parts.append(chunk[:take])
        cur += take
    return b"".join(parts)

def _mk_utf8_blob(rng: random.Random, target_len: int) -> bytes:
    parts: List[bytes] = []
    cur = 0
    while cur < target_len:
        if rng.random() < 0.6:
            chunk = _mk_ascii_blob(rng, rng.randint(1, 32))
        else:
            s = rng.choice(UTF8_FRAGMENTS)
            # Strict encode; our list avoids surrogates.
            chunk = s.encode('utf-8')
        take = min(len(chunk), target_len - cur)
        parts.append(chunk[:take])
        cur += take
    return b"".join(parts)

def _mk_binary_blob(rng: random.Random, target_len: int) -> bytes:
    parts: List[bytes] = []
    cur = 0
    while cur < target_len:
        mode = rng.randrange(5)
        if mode == 0:
            chunk = _rand_bytes(rng, rng.randint(1, 64))
        elif mode == 1:
            chunk = rng.choice(BIN_CHUNKS)
        elif mode == 2:
            base = rng.randrange(0, 256)
            span = rng.randint(16, 128)
            chunk = bytes(((base + i) & 0xFF) for i in range(span))
        elif mode == 3:
            pat = _rand_bytes(rng, rng.randint(1, 8))
            chunk = pat * rng.randint(4, 32)
        else:
            chunk = b"\x00" * rng.randint(1, 64)
        take = min(len(chunk), target_len - cur)
        parts.append(chunk[:take])
        cur += take
    return b"".join(parts)

def _inject_sentinels(rng: random.Random, buf: bytes) -> bytes:
    if not buf:
        return buf
    sentinels = [b"\x00", b"\xff", b"\x7f", b"\r\n", b"\n", b"\t"]
    barray = bytearray(buf)
    for s in sentinels:
        pos = rng.randrange(0, len(barray) + 1)
        barray[pos:pos] = s
        if len(barray) > MAX_TOTAL:
            barray = barray[:MAX_TOTAL]
            break
    return bytes(barray)

def _choose_length(rng: random.Random) -> int:
    roll = rng.random()
    if roll < 0.08:
        return 0
    if roll < 0.40:
        return rng.randint(1, 64)
    if roll < 0.75:
        return rng.randint(65, 512)
    if roll < 0.95:
        return rng.randint(513, 2048)
    return rng.randint(2049, MAX_TOTAL)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    target_len = _choose_length(rng)

    style = rng.randrange(3)
    if style == 0:
        base = _mk_ascii_blob(rng, target_len)
    elif style == 1:
        base = _mk_utf8_blob(rng, target_len)
    else:
        base = _mk_binary_blob(rng, target_len)

    if target_len > 0 and rng.random() < 0.7:
        base = _inject_sentinels(rng, base)

    if len(base) > MAX_TOTAL:
        base = base[:MAX_TOTAL]

    return base
